from fractions import Fraction

# Given values
a = [5, 15, 50, 150]
N = 4 # Since we are using a_1, a_2, a_3, a_4, we calculate A_3

# Helper function for D(x, y) = (a_x * a_y - 1) / (a_x - a_y)
def D(x, y, a_list):
    # Note: x and y are 1-indexed, list is 0-indexed
    ax = a_list[x-1]
    ay = a_list[y-1]

    numerator = ax * ay - 1
    denominator = ax - ay

    if denominator == 0:
        raise ValueError("a_x must not equal a_y")

    return Fraction(numerator, denominator)

# Calculate all necessary D(x, y) terms
D_terms = {}
for x in range(1, N + 1):
    for y in range(1, N + 1):
        if x != y:
            D_terms[(x, y)] = D(x, y, a)

# A_3 = Sum_{x=1}^4 Product_{y!=x} D(x, y)
A3 = Fraction(0)
for x in range(1, N + 1):
    product = Fraction(1)
    for y in range(1, N + 1):
        if y != x:
            product *= D_terms[(x, y)]
    A3 += product

print(f"Calculated A_3: {A3}")
# Convert to float for easier comparison, though fraction is exact
print(f"A_3 as float: {float(A3)}")
